<?php require 'config.php';$pageTitle='Giỏ hàng';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);if(isset($_POST['update'])&&isset($_POST['qty']))foreach($_POST['qty'] as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($qty,999);}header('Location: cart.php');exit;}$items=[];$total=0;if(!empty($_SESSION['cart'])){$ids=array_map('intval',array_keys($_SESSION['cart']));$in=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT * FROM products WHERE product_id IN ($in)");$st->execute($ids);foreach($st->fetchAll() as $p){$qty=min((int)$_SESSION['cart'][$p['product_id']],(int)$p['quantity']);$p['cart_qty']=$qty;$p['line_total']=$qty*$p['price'];$total+=$p['line_total'];$items[]=$p;}}require 'includes/header.php';?><h1 class="section-title">Giỏ hàng</h1><?php if(!$items): ?><div class="content-card"><p>Giỏ hàng đang trống.</p><a class="btn btn-red" href="products.php">Mua sắm ngay</a></div><?php else: ?><form method="post"><div class="table-responsive content-card"><table class="table"><thead><tr><th>Sản phẩm</th><th>Đơn giá</th><th style="width:130px">Số lượng</th><th>Thành tiền</th><th></th></tr></thead><tbody><?php foreach($items as $p): ?><tr><td><?= e($p['product_name']) ?></td><td><?= money($p['price']) ?></td><td><input class="form-control" type="number" min="0" name="qty[<?= $p['product_id'] ?>]" value="<?= $p['cart_qty'] ?>"></td><td><?= money($p['line_total']) ?></td><td><button class="btn btn-sm btn-outline-danger" name="remove" value="<?= $p['product_id'] ?>">Xóa</button></td></tr><?php endforeach; ?></tbody></table><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3"><button class="btn btn-outline-dark" name="update" value="1">Cập nhật giỏ hàng</button><div class="fs-5">Tổng cộng: <strong class="price"><?= money($total) ?></strong> <a class="btn btn-red ms-2" href="checkout.php">Đặt hàng</a></div></div></div></form><?php endif; ?><?php require 'includes/footer.php';?>
